{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "沈墨宁",
      "role": "protagonist",
      "identity": "古董鉴定师，文物修复世家出身，前拍卖行鉴定助理",
      "traits": ["专业偏执", "冷静理智", "渴望被认可", "缺乏江湖经验", "嘴硬心软"],
      "overt_motivation": "把离婚分得的青花罐变现，在古董行站稳脚跟，经济独立",
      "covert_motivation": "证明自己的专业价值，摆脱'豪门花瓶'的标签，获得职业尊严",
      "secret_fear": "被人发现自己其实不懂行规江湖，只是个有学历没经验的'书呆子'，再次被当成笑话",
      "misperception_of_other": "认为韩叙接近她是想从青花罐上分一杯羹，认为秦守业只是普通的压价商人",
      "hidden_connection": "外公沈怀瑾三十年前修复过与青花罐同一窑口的残件，这是她能识别孤品的关键"
    },
    {
      "name": "韩叙",
      "role": "deuteragonist",
      "identity": "专攻文物纠纷的律师，前检察官",
      "traits": ["逻辑缜密", "外冷内热", "原则性强", "不轻易信任"],
      "overt_motivation": "接手沈墨宁的法律案件，帮她应对前夫家的追讨",
      "covert_motivation": "弥补曾经因证据不足放走文物走私犯的遗憾，找回职业信念",
      "secret_fear": "再次因为自己的判断失误导致正义无法伸张",
      "misperception_of_other": "初期认为沈墨宁只是运气好捡到漏，后来才发现她的专业功底",
      "hidden_connection": "五年前经手过一起涉及傅家的文物走私案，当时因证据不足败诉"
    }
  ],
  "supporting_characters": [
    {
      "name": "傅明远",
      "function": "阻碍",
      "identity": "沈墨宁前夫，傅家长子",
